  // public control pipeline: valid / first / last aligned with the per-coefficient decision (stage 31)
  reg [31:0] vp, fp, lp, f2p;
  always @(posedge clk) begin vp <= {vp[30:0], vin}; fp <= {fp[30:0], first}; lp <= {lp[30:0], last}; f2p <= {f2p[30:0], first}; end
  assign cdec = {x4476, x4475, x4474}; assign cvalid = vp[30];
  reg fprev; always @(posedge clk) fprev <= fp[30];
  wire init_p = fp[30] | fprev;                 // first two coefficients start the two chains

  // accumulator: acc_in = init ? (1,0,0) : acc_out ; acc_out = HPC2(acc_in, b)  (two interleaved chains)
  wire [2:0] bsh = {x4476, x4475, x4474};
  wire [2:0] acc_out; wire [2:0] acc_in = init_p ? 3'b001 : acc_out;
  hpc2 uacc (.clk(clk), .a(acc_in), .b(bsh), .r(rnd[269:267]), .c(acc_out));
  reg [2:0] acc_last;
  always @(posedge clk) acc_last <= acc_out;
  hpc2 ufin (.clk(clk), .a(acc_last), .b(acc_out), .r(rnd[272:270]), .c(dec));

  reg [3:0] lastp; always @(posedge clk) lastp <= {lastp[2:0], lp[30]};
  assign dvalid = lastp[3];
